const buildSeverityCounts = (findings = []) => {
  const counts = Object.fromEntries(severityItems.map(item => [item.key, 0]));

  findings.forEach((finding) => {
    const rawSeverity = String(finding?.severity || '').toLowerCase();
    const severity = severityItems.find(item => item.key.toLowerCase() === rawSeverity)?.key || 'Info';
    counts[severity] += 1;
  });

  return counts;
};

const allocateSeverityCounts = (totalActive, severityCounts) => {
  const total = Math.max(0, Number(totalActive || 0));
  const keys = severityItems.map(item => item.key);
  const weights = keys.map(key => severityCounts[key] || 0);
  const weightTotal = weights.reduce((sum, w) => sum + w, 0);

  if (total === 0 || weightTotal === 0) {
    return Object.fromEntries(keys.map(key => [key, 0]));
  }

  const allocations = keys.map((key, index) => {
    const exact = (total * weights[index]) / weightTotal;
    const value = Math.floor(exact);
    return {
      key,
      value,
      remainder: exact - value,
    };
  });

  let remaining = total - allocations.reduce((sum, item) => sum + item.value, 0);
  allocations.sort((left, right) => right.remainder - left.remainder);

  for (let index = 0; index < allocations.length && remaining > 0; index += 1) {
    allocations[index].value += 1;
    remaining -= 1;
  }

  return Object.fromEntries(allocations.map(item => [item.key, item.value]));
};

