.vulnerability-count-box.active {
  border-color: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-feedback) 65%, #000000);
}

.vulnerability-count-box.mitigated {
  border-color: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-resolved) 65%, #000000);
}

.vulnerability-count-box strong {
  font-size: 2.35rem;
  line-height: 0.95;
